// HOW MUCH?! — monthly "map update" Reel (1080x1920, 30 fps, 120 BPM grid)
// Data: monthly-data.ts (generated by scripts/monthly_data.py) + gapmap-data.ts (all-time places per Bezirk).
// Blocks with no data (price moves, owner-confirmed prices) are skipped automatically.
import React, { useEffect, useState } from "react";
import { AbsoluteFill, Easing, continueRender, delayRender, interpolate, spring, useCurrentFrame, useVideoConfig } from "remotion";
import { BRAND, a, g, applyTheme, loadBrandFonts, Theme } from "./brand";
import { Accented, Backdrop, Bloom, Sfx, Sub, entrance, typed } from "./PriceVideo";
import { DISTRICTS, MAP_H, MAP_W } from "./gapmap-data";
import { MONTH } from "./monthly-data";

const BEAT = 15;
const clamp = { extrapolateLeft: "clamp", extrapolateRight: "clamp" } as const;
const MAP_X = 80;
const MAP_Y = 760;
const MAP_S = 0.89; // safe band: map spans x 80–899, y 760–1396

type Moves = { label: string; up: number; down: number }[];
const moves = MONTH.moves as unknown as Moves;
const per = MONTH.per as unknown as Record<string, { prices: number; places: number }>;
const owner = MONTH.owner_confirmed as number;

// timeline (frames), optional blocks only when there is data
const T = (() => {
  let t = 0;
  const s: Record<string, [number, number]> = {};
  const add = (k: string, beats: number) => { s[k] = [t, t + beats * BEAT]; t += beats * BEAT; };
  add("hook", 4);
  add("totals", 6);
  add("top", 6);
  if (moves.length) add("moves", 6);
  if (owner > 0) add("owner", 4);
  add("zero", 5);
  add("end", 6);
  return { s, total: t };
})();
export const MONTHLY_FRAMES = T.total;
const at = (k: string) => T.s[k]?.[0] ?? Infinity;

const Lines: React.FC<{ k: string; label: string; lines: string[]; accent: string; de?: string; size?: number; children?: React.ReactNode }> = ({ k, label, lines, accent, de, size = 112, children }) => {
  const f = useCurrentFrame();
  const { fps } = useVideoConfig();
  const [from, to] = T.s[k] ?? [0, -1];
  if (f < from - 2 || f > to) return null;
  const out = k === "end" ? 1 : interpolate(f, [to - 7, to], [1, 0], clamp);
  const lf = f - from;
  const kinds = ["slam", "snapLeft", "rise"] as const;
  return (
    <div style={{ position: "absolute", top: 300, left: 80, right: 180, opacity: out, transform: `translateY(${(1 - out) * -30}px)` }}>
      <div style={{ fontFamily: BRAND.mono, fontWeight: 700, fontSize: 32, letterSpacing: 6, color: BRAND.green, marginBottom: 18 }}>{typed(label, lf, 0, 12)}</div>
      {lines.map((ln, i) => (
        <div key={i} style={{ fontFamily: BRAND.heading, fontWeight: 700, fontSize: Math.min(size, Math.floor(820 / (ln.replace(/\*/g, "").length * 0.53))), lineHeight: 1.04, letterSpacing: -3, color: BRAND.text, whiteSpace: "nowrap", ...entrance(kinds[i % 3], lf, i * 5, fps) }}>
          <Accented text={ln} accent={accent} glow />
        </div>
      ))}
      <Sub text={de} style={{ marginTop: 16, fontSize: 42, opacity: interpolate(lf, [12, 20], [0, 1], clamp) }} />
      {children}
    </div>
  );
};

export const MonthlyMap: React.FC<{ theme?: Theme }> = ({ theme = "dark" }) => {
  applyTheme(theme);
  const f = useCurrentFrame();
  const { fps } = useVideoConfig();
  const [h] = useState(() => delayRender("fonts"));
  useEffect(() => {
    loadBrandFonts().then(() => continueRender(h)).catch(() => continueRender(h));
  }, [h]);

  const active = DISTRICTS.filter((d) => (per[d.nr]?.prices ?? 0) > 0).sort((x, y) => per[y.nr].prices - per[x.nr].prices);
  const top = active.slice(0, 5);
  const maxP = Math.max(1, ...active.map((d) => per[d.nr].prices));
  const zeros = DISTRICTS.filter((d) => d.n === 0);
  const fillAt = (nr: number) => {
    const i = active.findIndex((d) => d.nr === nr);
    return i < 0 ? Infinity : at("totals") + 4 + i * 5;
  };
  const draw = interpolate(f, [4, 40], [0, 1], { ...clamp, easing: Easing.inOut(Easing.cubic) });
  const endP = interpolate(f, [at("end") - 4, at("end") + 8], [0, 1], { ...clamp, easing: Easing.out(Easing.cubic) });
  const zeroOn = f >= at("zero") && f < at("end");
  const zeroPulse = 0.5 + 0.5 * Math.sin(((f - at("zero")) / BEAT) * Math.PI);
  const inTop = f >= at("top") && f < (T.s.top?.[1] ?? 0);

  return (
    <AbsoluteFill style={{ backgroundColor: BRAND.bg }}>
      <Backdrop />
      {active.map((d) => <Sfx key={d.nr} at={fillAt(d.nr)} src="pluck_001" volume={0.3} />)}
      {Object.keys(T.s).filter((k) => k !== "hook").map((k) => <Sfx key={k} at={at(k)} src={k === "zero" ? "glitch_002" : k === "end" ? "confirmation_002" : "maximize_006"} volume={0.45} />)}

      {/* map */}
      <div style={{ position: "absolute", left: MAP_X, top: MAP_Y, width: MAP_W, height: MAP_H, opacity: 1 - 0.88 * endP, transform: `scale(${MAP_S * (1 - 0.06 * endP)})`, transformOrigin: "0 0" }}>
        <svg width={MAP_W} height={MAP_H} viewBox={`0 0 ${MAP_W} ${MAP_H}`} style={{ overflow: "visible" }}>
          {DISTRICTS.map((d) => {
            const p = per[d.nr]?.prices ?? 0;
            const fp = p > 0 ? spring({ frame: f - fillAt(d.nr), fps, config: { damping: 14, stiffness: 160 } }) : 0;
            const isTop = inTop && top.some((t) => t.nr === d.nr);
            const isZero = zeroOn && d.n === 0;
            const strength = 0.25 + 0.6 * Math.sqrt(p / maxP);
            const dim = zeroOn ? 0.35 : inTop && !isTop ? 0.35 : 1;
            const fill = isZero ? a(BRAND.pink, 0.08 + 0.12 * zeroPulse) : p > 0 ? a(BRAND.green, strength * Math.min(1, fp) * dim) : "transparent";
            return (
              <path key={d.nr} d={d.d} pathLength={1} fill={fill}
                stroke={isZero ? BRAND.pink : isTop ? BRAND.green : BRAND.muted}
                strokeWidth={isZero || isTop ? 3.5 : 2}
                strokeDasharray={isZero ? "0.012 0.008" : `${draw} 1`}
                strokeLinejoin="round"
                style={{ filter: isZero ? `drop-shadow(0 0 ${6 + 8 * zeroPulse}px ${g(BRAND.pink, 0.8)})` : isTop ? `drop-shadow(0 0 10px ${g(BRAND.green, 0.7)})` : undefined }} />
            );
          })}
        </svg>
        {zeros.map((d, i) => {
          const p = spring({ frame: f - at("zero") - i * 2, fps, config: { damping: 9, stiffness: 220, mass: 0.6 } });
          return (
            <div key={d.nr} style={{ position: "absolute", left: d.cx, top: d.cy, transform: `translate(-50%,-50%) scale(${zeroOn ? p : 0})`, textAlign: "center", whiteSpace: "nowrap" }}>
              <div style={{ fontFamily: BRAND.mono, fontWeight: 700, fontSize: 46, lineHeight: 1, color: BRAND.pink, textShadow: `0 0 18px ${g(BRAND.pink, 0.6)}` }}>0</div>
              <div style={{ fontFamily: BRAND.mono, fontWeight: 700, fontSize: 19, letterSpacing: 1, color: BRAND.pink, marginTop: 2 }}>{d.name.toUpperCase()}</div>
            </div>
          );
        })}
      </div>

      <Lines k="hook" label={`WIEN · ${MONTH.month_en.toUpperCase()}`} lines={["What changed", "on the *map*?"]} accent={BRAND.green} de={`Was hat sich getan? · ${MONTH.month_de}`} />
      <Lines k="totals" label="THIS MONTH · DIESEN MONAT" lines={[`*+${MONTH.prices}* prices.`, `*+${MONTH.places}* places.`]} accent={BRAND.green} de={`+${MONTH.prices} Preise · +${MONTH.places} Lokale`} size={120} />
      <Lines k="top" label="MOST ACTIVE · AKTIVSTE BEZIRKE" lines={[]} accent={BRAND.green}>
        <div style={{ marginTop: 4 }}>
          {top.map((d, i) => {
            const lf = f - at("top") - i * 4;
            const p = interpolate(lf, [0, 12], [0, 1], { ...clamp, easing: Easing.out(Easing.cubic) });
            const n = per[d.nr].prices;
            return (
              <div key={d.nr} style={{ display: "flex", alignItems: "center", gap: 20, height: 74, opacity: p, transform: `translateX(${(1 - p) * -40}px)` }}>
                <div style={{ width: 350, fontFamily: BRAND.heading, fontWeight: 700, fontSize: 44, color: BRAND.text, whiteSpace: "nowrap" }}>{d.name}</div>
                <div style={{ height: 30, width: 380 * (n / maxP) * p, background: BRAND.green, borderRadius: 4, boxShadow: `0 0 18px ${g(BRAND.green, 0.5)}` }} />
                <div style={{ fontFamily: BRAND.mono, fontWeight: 700, fontSize: 40, color: BRAND.green }}>+{n}</div>
              </div>
            );
          })}
        </div>
      </Lines>
      {moves.length > 0 && (
        <Lines k="moves" label="SAME PLACE · NEW PRICE" lines={[]} accent={BRAND.green} de="Gleiches Lokal, neuer Preis">
          {moves.slice(0, 4).map((m, i) => {
            const p = interpolate(f - at("moves") - i * 4, [0, 12], [0, 1], clamp);
            return (
              <div key={m.label} style={{ display: "flex", gap: 30, alignItems: "baseline", height: 80, opacity: p }}>
                <div style={{ width: 360, fontFamily: BRAND.heading, fontWeight: 700, fontSize: 52, color: BRAND.text }}>{m.label}</div>
                <div style={{ fontFamily: BRAND.mono, fontWeight: 700, fontSize: 48, color: BRAND.pink }}>▲ {m.up}</div>
                <div style={{ fontFamily: BRAND.mono, fontWeight: 700, fontSize: 48, color: BRAND.green }}>▼ {m.down}</div>
              </div>
            );
          })}
        </Lines>
      )}
      {owner > 0 && <Lines k="owner" label="✓ VERIFIED" lines={[`*${owner}* prices`, "confirmed by owners."]} accent={BRAND.green} de={`${owner} Preise vom Lokal bestätigt`} size={100} />}
      <Lines k="zero" label={zeros.slice(0, 3).map((d) => d.name.toUpperCase()).join(" · ") + " …"} lines={[`Still at *zero*:`, `${zeros.length} Bezirke.`]} accent={BRAND.pink} de={`Noch bei null: ${zeros.length} Bezirke.`} />

      {f >= at("end") - 4 && (
        <AbsoluteFill>
          <Bloom color={a(BRAND.green, 0.85 * (BRAND.glow as number))} start={at("end")} top={720} size={900} />
          <div style={{ position: "absolute", top: 520, left: 80, width: 820, textAlign: "center", ...entrance("slam", f - at("end"), 0, fps, "center") }}>
            <div style={{ fontFamily: BRAND.heading, fontWeight: 700, fontSize: 112, letterSpacing: -3, color: BRAND.text }}>Add <Accented text="*yours*." accent={BRAND.green} glow /></div>
            <div style={{ fontFamily: BRAND.heading, fontWeight: 500, fontSize: 44, color: BRAND.muted, marginTop: 6 }}>Trag deinen Preis ein.</div>
          </div>
          <div style={{ position: "absolute", top: 760, left: 80, width: 820, textAlign: "center", ...entrance("rise", f - at("end"), 6, fps, "center") }}>
            <div style={{ fontFamily: BRAND.heading, fontWeight: 700, fontSize: 96, letterSpacing: -2, color: BRAND.green, textShadow: `0 0 26px ${g(BRAND.green, 0.5)}` }}>howmuch.live</div>
            <div style={{ fontFamily: BRAND.mono, fontWeight: 500, fontSize: 32, color: BRAND.muted, marginTop: 10 }}>link in bio · Link in Bio</div>
          </div>
          <div style={{ position: "absolute", top: 1010, left: 80, width: 820, textAlign: "center", ...entrance("rise", f - at("end"), 12, fps, "center") }}>
            <div style={{ fontFamily: BRAND.mono, fontWeight: 700, fontSize: 40, letterSpacing: 2, color: BRAND.yellow }}>NEXT UPDATE · {MONTH.next_en.toUpperCase()}</div>
            <div style={{ fontFamily: BRAND.mono, fontWeight: 500, fontSize: 30, color: BRAND.muted, marginTop: 8 }}>Nächstes Update: {MONTH.next_de}</div>
          </div>
        </AbsoluteFill>
      )}

      <div style={{ position: "absolute", top: 1440, left: 80, right: 80, textAlign: "center", fontFamily: BRAND.mono, fontWeight: 500, fontSize: 22, color: BRAND.muted, opacity: interpolate(f, [at("end"), at("end") + 10], [0, 0.9], clamp) }}>
        Prices dated {MONTH.month_en} · HOW MUCH?! community · Map: data.wien.gv.at (CC BY 4.0)
      </div>
      <div style={{ position: "absolute", top: 0, left: 0, height: 8, width: `${(f / (MONTHLY_FRAMES - 1)) * 100}%`, background: BRAND.green }} />
      <div style={{ position: "absolute", top: 190, left: 80, right: 80, display: "flex", justifyContent: "space-between", fontFamily: BRAND.mono, fontSize: 28, letterSpacing: 2, opacity: 1 - endP }}>
        <span style={{ color: BRAND.green, fontWeight: 700 }}>HOW MUCH?!</span>
        <span style={{ color: BRAND.muted, fontWeight: 500 }}>MONTHLY · {MONTH.month_en.toUpperCase()}</span>
      </div>
    </AbsoluteFill>
  );
};
